(3320,"شیک اینڈ بیک ایکسٹراویگینزا کوٹنگ مکس","صبر صرف ایک خوبی نہیں، یہ ایک ہنر ہے۔ بالکل کھانا پکانے کی طرح، ہمدردی پیدا کرنا بھی ایک ہنر ہے جسے نکھارا جا سکتا ہے، جیسا کہ مینیسوٹا سے ڈا وِیٹا (DaVita) کی گردوں کی ماہرِ غذائیت میری نے ثابت کیا ہے۔ میری نے \"مریضوں کے ساتھ صبر\" کے اپنے ہنر کو بھی نکھارا ہے، اور مزیدار ترکیبیں بنانے کی اپنی ایجاد پسندی کو بھی، جیسے ان کا گردوں کے لیے موزوں شیک اینڈ بیک ایکسٹراویگینزا کوٹنگ مکس۔","3","1 کپ کوٹنگ مکس، 1-2 پاؤنڈ چکن یا پورک چاپس پر لگانے کے لیے",
["1-1/2 کپ باریک خشک بریڈ کرمبز","1 کپ سفید میدہ","4 کھانے کے چمچ خشک اجوائن کی پتی (parsley)","1 کھانے کا چمچ پاپریکا","2 چائے کے چمچ پیاز کا پاؤڈر","1-1/2 چائے کے چمچ لہسن کا پاؤڈر","1 چائے کا چمچ کالی مرچ","1 کھانے کا چمچ مارجورم","1 کھانے کا چمچ تھائم","3 کھانے کے چمچ سبزیوں کا تیل"],
["بریڈ کرمبز، میدہ، پارسلے، پاپریکا، پیاز کا پاؤڈر، لہسن کا پاؤڈر، کالی مرچ، مارجورم اور تھائم کو ملا لیں۔ یکساں طور پر ملانے کے لیے ہلائیں۔","بریڈ کرمبز کے مرکب میں تیل ڈالیں اور کانٹے سے اچھی طرح مکمل طور پر ملائیں۔","ہوا بند ڈبے میں ٹھنڈی، خشک جگہ پر رکھیں یا فریزر میں محفوظ کریں۔","استعمال کے لیے 1 کپ کوٹنگ مکسچر ایک پلاسٹک بیگ میں ڈالیں۔ چکن یا دوسرے گوشت کے چند ٹکڑے ڈالیں اور ہلا کر کوٹ کریں۔","گوشت کو چکنائی لگی ہوئی بیکنگ ٹرے پر 375° F پر بیک کریں، 20 منٹ بیک کرنے کے بعد ایک بار پلٹ دیں۔ گوشت کے تھرمامیٹر کے مطابق گوشت کے تیار ہونے تک پکاتے رہیں۔ (وقت گوشت کی قسم اور موٹائی کے مطابق مختلف ہوتا ہے)۔"],
["اس ترکیب سے 3 کھانوں کے لیے کافی کوٹنگ مکس بنتا ہے۔ باقی مرکب کو بند ڈبے یا فریزر بیگ میں رکھ کر دوبارہ استعمال تک فریز کر دیں۔","گھر پر خشک بریڈ کرمبز بنانے کے لیے ایک دن پرانی ڈبل روٹی کو کرکری ہونے تک ٹوسٹ کریں، جلنے نہ دیں۔ بلینڈر یا فوڈ پروسیسر میں پیس لیں۔","یہ چکن کے لیے بہترین کوٹنگ ہے یا کسی بھی ترکیب میں بریڈ کرمبز کی جگہ استعمال کیا جا سکتا ہے۔"],
["1 نشاستہ","1/2 چکنائی"]),
